INSERT OR IGNORE INTO questions (id,question_type,school_level,difficulty,stem_json,answer_json,explanation_json,status,source_content_id,curriculum_version_id,marks) VALUES
('q-mangrove-1','multiple_choice','P6',2,'{"prompt":"What is one direct way mangrove roots protect a coastline?","options":["They make seawater warmer.","They slow down waves before they reach the shore.","They remove all mud from the coast.","They stop every storm from forming."]}','{"correctOption":1}','{"text":"The first paragraph states that the roots slow down waves, reducing the force of moving water."}','published','starter-mangroves','SG-PRIMARY-ENGLISH-2020-PSLE-2026',1),
('q-mangrove-2','short_answer','P6',3,'{"prompt":"Why does the passage say mangroves can serve two purposes for communities?"}','{"acceptedKeywords":["wildlife","coast","coastal","protect","resilience"],"modelAnswer":"They support wildlife while also helping coastal areas become more resilient to waves and erosion."}','{"text":"A complete answer should identify both the ecological and coastal-protection benefits."}','published','starter-mangroves','SG-PRIMARY-ENGLISH-2020-PSLE-2026',2),
('q-space-1','multiple_choice','P6',2,'{"prompt":"Why can astronauts lose muscle and bone strength in space?","options":["They cannot eat in space.","Microgravity reduces the normal physical load on the body.","Spacecraft are too cold for exercise.","Astronauts are not allowed to stand."]}','{"correctOption":1}','{"text":"The passage explains that the body does not work against gravity in the usual way."}','published','starter-space-exercise','SG-PRIMARY-ENGLISH-2020-PSLE-2026',1),
('q-space-2','short_answer','P6',3,'{"prompt":"How does exercise help astronauts beyond simply keeping them fit?"}','{"acceptedKeywords":["mission","work","return","Earth","readapt","gravity"],"modelAnswer":"It helps them work effectively during missions and prepares their bodies to return and readapt to Earth gravity."}','{"text":"Use information from the third paragraph."}','published','starter-space-exercise','SG-PRIMARY-ENGLISH-2020-PSLE-2026',2),
('q-waste-1','multiple_choice','P5',2,'{"prompt":"What does the writer suggest doing before food becomes waste?","options":["Order extra food in case someone is hungry.","Plan the portion and amount of food more carefully.","Finish every meal even when full.","Avoid eating at hawker centres."]}','{"correctOption":1}','{"text":"The passage emphasises planning before ordering instead of forcing oneself to finish too much food."}','published','starter-hawker-waste','SG-PRIMARY-ENGLISH-2020-PSLE-2026',1),
('q-waste-2','short_answer','P5',2,'{"prompt":"Why can small choices have a wider effect?"}','{"acceptedKeywords":["many","people","habits","less","food","discarded","resources"],"modelAnswer":"When many people repeat thoughtful habits, less food is discarded and fewer resources are wasted."}','{"text":"The final paragraph links individual habits with community-level impact."}','published','starter-hawker-waste','SG-PRIMARY-ENGLISH-2020-PSLE-2026',2);

